function mergeWithCopy(nums1, m, nums2, n) {
  const first = nums1.slice(0, m);        // a safe copy of nums1's values
  let i = 0, j = 0, k = 0;
  while (i < m && j < n) nums1[k++] = first[i] <= nums2[j] ? first[i++] : nums2[j++];
  while (i < m) nums1[k++] = first[i++];
  while (j < n) nums1[k++] = nums2[j++];
}

function merge(nums1, m, nums2, n) {
  let i = m - 1;          // last real value in nums1
  let j = n - 1;          // last value in nums2
  let k = m + n - 1;      // slot to fill, from the back
  while (j >= 0) {
    if (i >= 0 && nums1[i] > nums2[j]) {
      nums1[k--] = nums1[i--];
    } else {
      nums1[k--] = nums2[j--];
    }
  }
}

